#include <bits/stdc++.h>using namespace std;#define int long longinline void fmx(int &a,int b){ if(a<b) a=b; }#define go(i,a,b) for(int i=a;i<=b;i++)#define og(i,a,b) for(int i=b;i>=a;i--)int T,n,ans; void O_o(){    cin >> n;    vector<int> a(n + 1), oth;    go(i,1,n) cin >> a[i];    sort(a.begin() + 1,a.begin() + n + 1);    int tot = 0, p = 0;    for(int i=1;i<=n;){        if(i < n && a[i] == a[i + 1]){            tot += a[i] * 2;            p++;            i += 2;        }        else{            oth.emplace_back(a[i]);            i++;        }    }    ans = 0;    if(p >= 2) ans = tot;    og(i,0,(int)oth.size() - 1){        if(oth[i] < tot){            fmx(ans,tot + oth[i]);            break;        }    }    og(i,0,(int)oth.size() - 2){        if(oth[i + 1] - oth[i] < tot){            fmx(ans,tot + oth[i] + oth[i + 1]);        }    }    cout << ans << '\n';} signed main(){    ios::sync_with_stdio(false);    cin.tie(nullptr); cout.tie(nullptr);    cin >> T;    while(T--) O_o();}